INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(125302, 'ruRU', '', 'Как трагично!', 24330),
(125303, 'ruRU', '', 'Ох нет, плохие времена...', 24330),
(125304, 'ruRU', '', 'Ох нет, я не могу смотреть...', 24330),
(125327, 'ruRU', '', 'Архимаг Альтурус и я можем удерживать подкрепление от достижения ворот, но сделай всё возможное, чтобы отбросить их, $n.$B$BЕсли их силы продолжат расти, мы можем не удержать позицию.', 24330),
(125337, 'ruRU', '', 'Истребитель $n! На нас наступают рои демонов! Твоё присутствие требуется на борту Демонического Молота!', 24330),
(125340, 'ruRU', '', 'Гори, детка, гори!', 24330),
(125341, 'ruRU', '', 'Горячо!', 24330),
(125342, 'ruRU', '', 'Жутковато!', 24330),
(125343, 'ruRU', '', 'Горит...', 24330),
(125344, 'ruRU', '', 'Я люблю порталы.', 24330),
(125375, 'ruRU', '', '|TInterface\\Icons\\SPELL_SHADOW_SHADETRUESIGHT.BLP:20|t %s начинает использовать |cFFFF0000|Hspell:228565\n|h[Осквернённое дыхание]|h|r!', 24330),
(125378, 'ruRU', '', 'Истребитель $n, нам нужна помощь твоих острых глеф, чтобы сдержать этих демонов!', 24330),
(125395, 'ruRU', '', 'Вы заплатите за то, что держали меня в плену, мерзкие создания!', 24330),
(125397, 'ruRU', '', 'Отвратительный демон!', 24330),
(125399, 'ruRU', '', 'Кто нашшёл — тот и забрал!', 24330),
(125403, 'ruRU', '', 'Иду, мать!', 24330),
(125404, 'ruRU', '', 'Матрона-мать Злоба злобно глядит на Кор''вас.', 24330),
(125405, 'ruRU', '', 'Не думай, что ты встретишь эту вершину без меня, Повелитель Смерти. Вперёд!', 24330),
(125406, 'ruRU', '', 'Демонический Молот — НАШ корабль. Время напомнить демонам об этом факте!', 24330),
(125407, 'ruRU', '', 'Ещё демонссы... Хотя я надеялассь на немного развлечений на борту, это было не то, что я имела в виду.', 24330),
(125408, 'ruRU', '', 'Истребитель $n, рад, что ты вернулся! На этот раз они настроены серьёзно!', 24330),
(125409, 'ruRU', '', 'Мардум потерян. Скатертью дорога, если спросишь меня. Хотя было бы неудобно потерять ещё и Демонический Молот.', 24330),
(125411, 'ruRU', '', 'Так и должно было случиться. Нам больше не нужен Ночной Колодец, ни его силы.$b$bМы должны выковать собственную судьбу.', 24330),
(125412, 'ruRU', '', 'Ночного Колодца больше нет.$b$bЭти Ночнорождённые научатся выживать без его развращающей силы, или они погибнут. Будем надеяться на первое.', 24330),
(125413, 'ruRU', '', 'Я всегда буду задаваться вопросом, что могло бы быть, если бы мы решили сохранить Ночной Колодец. Кто мы без его силы?$b$bВ конце концов, я доверяю суждению Талисры. Под её руководством я знаю, Ночнорождённые проложат новый путь.', 24330),
(125416, 'ruRU', '', 'Я впечатлён. Отпустить Ночной Колодец было непростой задачей.$b$bЕго сила и притягательность со временем угаснут. Как это было с нами, они найдут свой собственный путь в этом мире.', 24330),
(125417, 'ruRU', '', 'Мы не можем долго продержатьссся. Мы должны уничтожить эти корабли!', 24330),
(125418, 'ruRU', '', 'Приветствуем тебя на службе, Даумир! Запрыгивай, Повелитель Смерти. Время вернуться в Акерус.', 24330),
(125419, 'ruRU', '', 'Оружие сильно повреждено. Если мы активируем его сейчас, оно может уничтожить и нас... Возможно, если мы перенаправим энергию от главного ядра двигателя...', 24330),
(125420, 'ruRU', '', 'Ты отлично справился, маленький гном. Скоро никого не останется, чтобы противостоять могуществу Легиона!', 24330),
(125421, 'ruRU', '', 'Ты слишком поздно, смертный. Судьба Азерота предрешена.', 24330),
(125422, 'ruRU', '', 'Это безнадёжно. Мы повсюду. Мы — Легион!', 24330),
(125423, 'ruRU', '', 'Ты сильнее, чем я думал. Впрочем, не важно.', 24330),
(125424, 'ruRU', '', 'Твой мир, все миры, сгорят! Это твоя судьба!', 24330),
(125425, 'ruRU', '', 'Как это возможно? Ты НИЧТО!', 24330),
(125426, 'ruRU', '', 'Он... приближается...', 24330),
(125450, 'ruRU', '', 'Это нежелательное вторжение у нас под контролем. Будь так добр, проверь прозорливца Акалу, хорошо, Истребитель $n?', 24330),
(125475, 'ruRU', '', 'Посмотрим, где мы оказались, хорошо?', 24330),
(125476, 'ruRU', '', 'Хм. Из огня да в полымя. Что ж, по крайней мере здесь мы в лучшем положении для борьбы с Легионом.', 24330),
(125477, 'ruRU', '', 'У меня здесь есть небольшая уборка. Скоро увидимся, $n.', 24330);
